def link_accounts(apps, schema_editor):
    """يربط كل تلميذ مسائي بحسابه في المدرسة، أو يُنشئ له حساباً برقم القيد."""
    from django.contrib.auth.hashers import make_password
    EveningStudent = apps.get_model("quiz", "EveningStudent")
    User = apps.get_model("quiz", "User")
    for st in EveningStudent.objects.filter(user__isnull=True):
        user = User.objects.filter(matricule=st.matricule).first() or User.objects.filter(username=st.matricule).first()
        if user and user.role != "student":
            continue
        if user is None:
            user = User.objects.create(username=st.matricule, matricule=st.matricule, role="student",
                                       full_name=st.full_name, password=make_password(st.matricule))
        st.user = user
        st.save(update_fields=["user"])


